"""Seating rows built from a list of students."""

from typing import Iterable, List

from rosterkit.models import Student

def _check_seats(seats_per_row: int) -> None:
    if seats_per_row <= 0:
        raise ValueError(
            f"seats must be positive, got {seats_per_row}"
        )

def _ordered(students: Iterable[Student]) -> List[Student]:
    ordered = sorted(
        students, key=lambda s: (s.last_name, s.first_name)
    )
    if not ordered:
        raise ValueError("no students to seat")
    return ordered

def _chunk(
    ordered: List[Student], size: int
) -> List[List[Student]]:
    starts = range(0, len(ordered), size)
    return [ordered[start:start + size] for start in starts]

def _format_row(number: int, seats: List[Student]) -> str:
    names = [student.display_name for student in seats]
    return f"Row {number}: " + " | ".join(names)

# ---
def seat_rows(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One line of text per row, sorted by last name."""
    _check_seats(seats_per_row)
    rows = _chunk(_ordered(students), seats_per_row)
    numbered = enumerate(rows, 1)
    return [_format_row(n, row) for n, row in numbered]

