# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student

def _student(last_name, first_name):
    return Student("0", last_name, first_name, "A")

class SeatRowTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            _student("Quillon", "Sefa"),
            _student("Halloway", "Juno"),
            _student("Dunmere", "Piet")
        ]

    def test_sorted_by_last_name_and_chunked(self):
        expected = [
            "Row 1: Dunmere, Piet | Halloway, Juno",
            "Row 2: Quillon, Sefa"
        ]
        rows = seat_rows(self.students, 2)
        self.assertEqual(rows, expected)

    def test_one_row_when_seats_cover_everyone(self):
        rows = seat_rows(self.students, 5)
        self.assertEqual(len(rows), 1)
        self.assertEqual(rows[0].count("|"), 2)

    def test_same_last_name_sorted_by_first_name(self):
        students = [
            _student("Lee", "Zoe"),
            _student("Lee", "Amir")
        ]
        expected = ["Row 1: Lee, Amir | Lee, Zoe"]
        self.assertEqual(seat_rows(students, 2), expected)

    def test_zero_seats_rejected(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, 0)

    def test_negative_seats_rejected(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, -4)

    def test_no_students_rejected(self):
        with self.assertRaises(ValueError):
            seat_rows([], 2)
